INSERT INTO `email_templates` (`id`, `created_at`, `updated_at`, `is_deleted`, `deleted_at`, `name`, `subject`, `content`, `language`) VALUES
('54', '2025-12-04 16:12:36', '2026-03-12 12:13:43', 0, NULL, 'learn_serve_registration_confirmation', 'تأكيد تسجيل', '<p>عزيزي {{ user.get_full_name }},</p><p>شكراً لك على التسجيل لفرصة : <strong>{{ opportunity.title_en }}</strong>.</p><h3 style="margin-left:0;">تفاصيل الفرصة:</h3><p style="margin-left:0;"><strong>التاريخ:</strong> {{ opportunity.start_date|date:"F j, Y" }} {% if opportunity.end_date and opportunity.end_date != opportunity.start_date %} إلى {{ opportunity.end_date|date:"F j, Y" }} {% endif %}</p><p style="margin-left:0;">{% if opportunity.start_time and opportunity.end_time %}</p><p style="margin-left:0;"><strong>الوقت:</strong> {{ opportunity.start_time|time:"g:i A" }} - {{ opportunity.end_time|time:"g:i A" }}</p><p style="margin-left:0;">{% endif %} {% if opportunity.location_en %}</p><p style="margin-left:0;"><strong>الموقع:</strong> {{ opportunity.location_en }}</p><p style="margin-left:0;">{% endif %}</p><p>{% if link %}</p><p>يمكنك الانضمام إلى الاجتماع باستخدام الرابط أدناه:</p><p><a href="{{ link }}">{{ link }}</a></p><p>{% endif %}</p><p>يسعدنا انضمامك إلينا. يرجى التواصل معنا إذا كانت لديك أي أسئلة.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('26', '2025-12-04 16:12:36', '2026-03-12 12:46:27', 0, NULL, 'entity_profile_rejection', 'تم رفض الحساب', '<p>عزيزي {{ user.first_name }},</p><p>نأسف لإعلامك بأنه تم رفض حسابكم "<strong>{{ organization_name }}</strong>".</p><p><strong>السبب:</strong> {{ rejection_reason }}</p><p>إذا كانت لديك أي أسئلة، يرجى التواصل معنا.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('24', '2025-12-04 16:12:36', '2026-03-12 12:46:39', 0, NULL, 'entity_profile_approval', 'تمت الموافقة على الحساب', '<p>عزيزي {{ user.first_name }},</p><p>يسعدنا إعلامك بأنه تم الموافقة على حسابكم"<strong>{{ organization_name }}</strong>" بنجاح.</p><p>شكراً لك على جهودك ومساهمتك في منصتنا. نتطلع إلى استمرار مشاركتك.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('25', '2025-12-04 16:12:36', '2026-03-12 12:47:15', 0, NULL, 'entity_profile_rejection', 'Entity account Rejected', '<p>Dear {{ user.first_name }},</p><p>We regret to inform you that your entity account "<strong>{{ organization_name }}</strong>" has been rejected.</p><p><strong>Reason:</strong> {{ rejection_reason }}</p><p>If you have any questions, please feel free to contact us.</p><p>Best regards,<br>Forsa Team</p>', 'en'),
('43', '2025-12-04 16:12:36', '2026-03-12 12:27:39', 0, NULL, 'volunteer_unregistration_creator_notification', 'Volunteer Unregistered', '<p>Dear {{ opportunity.created_by.get_full_name }},</p><p>A volunteer has unregistered from your opportunity: <strong>{{ opportunity.title_en }}</strong></p><p style="margin-left:0;"><strong>Volunteer Name:</strong> {{ user.get_full_name }}</p><p style="margin-left:0;"><strong>Email:</strong> {{ user.email }}</p><p style="margin-left:0;"><strong>Unregistered on:</strong> {{ unregistered_at }}</p><p>You can review this and other registrations in your dashboard.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('14', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'forbidden_words_admin_email', 'تم اكتشاف كلمات محظورة في منشور', '<p>مرحباً المشرف,</p>\n                    <p>تم اكتشاف الكلمات المحظورة التالية في منشور بعنوان "<strong>{{ post_title }}</strong>" أنشأه {{ user.get_full_name }}:</p>\n                    <ul>\n                        {% for word in detected_words %}\n                        <li>{{ word }}</li>\n                        {% endfor %}\n                    </ul>\n                    <p>نتيجة لذلك، لن يتم عرض المنشور على المنصة.</p>\n                    <p>أطيب التحيات,<br>فريق Forsa</p>', 'ar'),
('41', '2025-12-04 16:12:36', '2026-03-12 12:27:48', 0, NULL, 'volunteer_registration_confirmation', 'Volunteer Registration Confirmation', '<p>Dear {{ user.get_full_name }},</p><p>Thank you for registering for the volunteer opportunity: <strong>{{ opportunity.title_en }}</strong>.</p><h3 style="margin-left:0;">Opportunity Details:</h3><p style="margin-left:0;"><strong>Date:</strong> {{ opportunity.start_date|date:"F j, Y" }} {% if opportunity.end_date and opportunity.end_date != opportunity.start_date %} to {{ opportunity.end_date|date:"F j, Y" }} {% endif %}</p><p style="margin-left:0;">{% if opportunity.start_time and opportunity.end_time %}</p><p style="margin-left:0;"><strong>Time:</strong> {{ opportunity.start_time|time:"g:i A" }} - {{ opportunity.end_time|time:"g:i A" }}</p><p style="margin-left:0;">{% endif %} {% if opportunity.location_en %}</p><p style="margin-left:0;"><strong>Location:</strong> {{ opportunity.location_en }}</p><p style="margin-left:0;">{% endif %}</p><p>{% if link %}</p><p>You can join via WhatsApp using the link below:</p><p><a href="{{ link }}">{{ link }}</a></p><p>{% endif %}</p><p>We are excited to have you on board. Please feel free to reach out if you have any questions.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('47', '2025-12-04 16:12:36', '2026-03-12 12:27:59', 0, NULL, 'volunteer_bulk_unregistration_notification', 'Bulk Volunteer Unregistration', '<p>Dear {{ user.get_full_name }},</p><p>You have been unregistered from the following volunteer opportunity by the opportunity owner:</p><p style="margin-left:0;"><strong>Opportunity:</strong> {{ opportunity.title_en }}</p><p style="margin-left:0;"><strong>Organizer:</strong> {{ opportunity.created_by.get_full_name }}</p><p style="margin-left:0;"><strong>Unregistered on:</strong> {{ unregistered_at }}</p><p>If you have any questions, please contact the opportunity organizer.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('38', '2025-12-04 16:12:36', '2026-03-12 12:31:08', 0, NULL, 'event_rejection_email', 'تم رفض الفعالية', '<p>عزيزي {{ user.first_name }},</p><p>نأسف لإعلامك بأنه تم رفض "<strong>{{ event_title }}</strong>".</p><p>السبب: <strong>{{ rejection_reason }}</strong></p><p>إذا كانت لديك أي أسئلة، يرجى التواصل معنا.</p>', 'ar'),
('44', '2025-12-04 16:12:36', '2026-03-12 12:50:38', 0, NULL, 'volunteer_unregistration_creator_notification', 'إلغاء تسجيل متطوع', '<p>عزيزي {{ opportunity.created_by.get_full_name }},</p><p>قام متطوع بإلغاء التسجيل لفرصتك: <strong>{{ opportunity.title_en }}</strong></p><p style="margin-left:0;"><strong>اسم المتطوع:</strong> {{ user.get_full_name }}</p><p style="margin-left:0;"><strong>البريد الإلكتروني:</strong> {{ user.email }}</p><p style="margin-left:0;"><strong>تم الإلغاء في:</strong> {{ unregistered_at }}</p><p>يمكنك مراجعة هذا التسجيل والتسجيلات الأخرى في لوحة التحكم الخاصة بك.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('40', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'volunteer_registration_creator_notification', 'تسجيل متطوع جديد', '<p>مرحباً {{ opportunity.created_by.first_name }},</p>\n                    <p>قام متطوع جديد بالتسجيل لفرصتك: <strong>{{ opportunity.title_en }}</strong></p>\n                    <div style="margin: 20px 0; padding: 15px; border: 1px solid #eee; border-radius: 5px;">\n                        <p><strong>تفاصيل المتطوع:</strong></p>\n                        <ul style="text-align: left; padding-left: 20px;">\n                            <li>الاسم: {{ volunteer.get_full_name }}</li>\n                            <li>البريد الإلكتروني: {{ volunteer.email }}</li>\n                            <li>وقت التسجيل: {{ registration_time }}</li>\n                        </ul>\n                    </div>\n                    <p>يمكنك عرض جميع التسجيلات لهذه الفرصة في لوحة التحكم الخاصة بك.</p>\n                    <p>شكراً لك على إنشاء الفرص مع Forsa!</p>', 'ar'),
('60', '2025-12-04 16:12:36', '2026-03-12 12:52:44', 0, NULL, 'opportunity_deletion_approved', 'تمت الموافقة على حذف الفرصة', '<p><strong>{{ user.get_full_name }}</strong></p><p>لقد تمت الموافقة على طلبك لحذف الفرصة&nbsp;</p><p><strong>{{ opportunity.title_en }}</strong></p><p>وتمت إزالتها بنجاح</p><p style="margin-left:0;">&nbsp;{{ opportunity.title_en }} <strong>:عنوان الفرصة</strong></p><p style="margin-left:0;">&nbsp;{{ approval_date }} <strong>:تاريخ الموافقة</strong></p><p>شكراً لك على استخدام منصتنا</p><p>مع اطيب التمنيات<br>فريق فرصة</p>', 'ar'),
('52', '2025-12-04 16:12:36', '2026-03-12 12:15:49', 0, NULL, 'learn_serve_registration_creator_notification', 'تسجيل جديد', '<p>مرحباً {{ opportunity.created_by.first_name }},</p><p>قام مشارك جديد بالتسجيل لفرصة تعلم وشارك الخاصة بك: <strong>{{ opportunity.title_en }}</strong></p><p style="margin-left:0;"><strong>تفاصيل المشارك:</strong></p><ul><li><p style="margin-left:0;">الاسم: {{ attendee.get_full_name }}</p></li><li><p style="margin-left:0;">البريد الإلكتروني: {{ attendee.email }}</p></li><li><p style="margin-left:0;">وقت التسجيل: {{ registration_time }}</p></li></ul><p>يمكنك عرض جميع التسجيلات لهذه الفرصة في لوحة التحكم الخاصة بك.</p><p>شكراً لك على إنشاء الفرص مع فرصة!</p>', 'ar'),
('49', '2025-12-04 16:12:36', '2026-03-12 12:26:13', 0, NULL, 'learn_serve_unregistration_notification', 'Unregistration', '<p>Dear {{ opportunity.created_by.get_full_name }},</p><p>A participant has unregistered from your Learn &amp; Share opportunity: <strong>{{ opportunity.title_en }}</strong></p><p><strong>Participant Name:</strong> {{ user.get_full_name }}</p><p><strong>Email:</strong> {{ user.email }}</p><p><strong>Unregistered on:</strong> {{ unregistered_at }}</p><p>You can review this and other registrations in your dashboard.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('61', '2025-12-04 16:12:36', '2026-03-12 12:42:16', 0, NULL, 'opportunity_deleted_notification', 'Opportunity Deleted', '<p>Dear {{ user.get_full_name }},</p><p>We regret to inform you that an opportunity you registered for has been deleted by the organizer.</p><p style="margin-left:0;"><strong>Opportunity:</strong> {{ opportunity.title_en }}</p><p style="margin-left:0;"><strong>Organizer:</strong> {{ opportunity.created_by.get_full_name }}</p><p style="margin-left:0;"><strong>Deleted on:</strong> {{ deletion_date }}</p><p>If you have any questions, please contact the opportunity organizer directly.</p><p>We apologize for any inconvenience this may cause. Please check our platform for other available opportunities that match your interests.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('79', '2025-12-04 16:12:36', '2026-03-12 12:35:46', 0, NULL, 'event_deletion_approved', 'Event Deletion Approved', '<p>Dear {{ user.get_full_name }},</p><p>Your request to delete the following event has been approved:</p><p style="margin-left:0;"><strong>Event:</strong> {{ event.title_en }}</p><p style="margin-left:0;"><strong>Request Date:</strong> {{ request_date }}</p><p style="margin-left:0;"><strong>Approved on:</strong> {{ approval_date }}</p><p>The event has been removed from our platform and is no longer visible to users. All registered participants have been notified about this change.</p><p>Thank you for using our platform. If you have any questions, please contact our support team.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('77', '2025-12-04 16:12:36', '2026-03-12 12:35:52', 0, NULL, 'event_deletion_rejected', 'Event Deletion Rejected', '<p>Dear {{ user.get_full_name }},</p><p>Your request to delete the following event has been rejected:</p><p style="margin-left:0;"><strong>Event:</strong> {{ event.title_en }}</p><p style="margin-left:0;"><strong>Request Date:</strong> {{ request_date }}</p><p style="margin-left:0;"><strong>Rejected on:</strong> {{ rejection_date }}</p><p style="margin-left:0;"><strong>Reason for Rejection:</strong> {{ rejection_reason }}</p><p>Your event remains active on our platform. If you have any questions about this decision or need further assistance, please contact our support team.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('80', '2025-12-04 16:12:36', '2026-03-12 12:37:36', 0, NULL, 'event_deletion_approved', 'تمت الموافقة على حذف الفعالية', '<p>عزيزي {{ user.get_full_name }},</p><p>لقد تمت الموافقة على طلب حذف الفعالية :</p><p style="margin-left:0;"><strong>الفعالية:</strong> {{ event.title_en }}</p><p style="margin-left:0;"><strong>تاريخ الطلب:</strong> {{ request_date }}</p><p style="margin-left:0;"><strong>تمت الموافقة في:</strong> {{ approval_date }}</p><p>تمت إزالة الفعالية من منصتنا ولم يعد ظاهراً للمستخدمين. تم إعلام جميع المشاركين المسجلين بهذا التغيير.</p><p>شكراً لك على استخدام منصتنا. إذا كانت لديك أي أسئلة، يرجى التواصل مع فريق الدعم لدينا.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('9', '2025-12-04 16:12:36', '2026-03-12 12:47:57', 0, NULL, 'forbidden_words_reply_user_email', 'Forbidden Words Detected in Your Reply', '<p style="text-align:center;"><strong>Hello {{ user.first_name|default:"User" }},</strong></p><p style="text-align:center;">The following forbidden words were detected in your reply:</p><p style="margin-left:0;">{% for word in detected_words %}</p><ul><li><p style="margin-left:0;text-align:center;">{{ word }}</p></li></ul><p style="margin-left:0;text-align:center;">{% endfor %}</p><p style="text-align:center;">As a result, your reply will not be displayed on the platform.</p><p style="text-align:center;">If you have any questions, please contact support.</p><p style="text-align:center;">Best regards,<br>Forsa Team</p>', 'en'),
('64', '2025-12-04 16:12:36', '2026-03-12 12:52:21', 0, NULL, 'fursa_friend_backup_notification', 'مطلوب دعم طوارئ من أصدقاء Forsa', '<p>عزيزي {{ friend.user.get_full_name }},</p><p><strong>طارئ:</strong> فرصة التطوع \'<strong>{{ opportunity.title_en }}</strong>\' تحتاج إلى متطوعين إضافيين.</p><h3 style="margin-left:0;">مطلوب دعم طوارئ</h3><p style="margin-left:0;">كصديق مميز في Forsa، مساعدتك مطلوبة عاجلاً لدعم فرصة التطوع هذه بغض النظر عن المهارات أو الاهتمامات.</p><p style="margin-left:0;"><strong>المتطوعون المطلوبون:</strong> {{ volunteers_needed }} إضافيين</p><h4 style="margin-left:0;">تفاصيل الفرصة:</h4><p style="margin-left:0;"><strong>التاريخ:</strong> {{ opportunity.start_date|date:"F j, Y" }} {% if opportunity.end_date and opportunity.end_date != opportunity.start_date %} إلى {{ opportunity.end_date|date:"F j, Y" }} {% endif %}</p><p style="margin-left:0;">{% if opportunity.start_time and opportunity.end_time %}</p><p style="margin-left:0;"><strong>الوقت:</strong> {{ opportunity.start_time|time:"g:i A" }} - {{ opportunity.end_time|time:"g:i A" }}</p><p style="margin-left:0;">{% endif %} {% if opportunity.location_en %}</p><p style="margin-left:0;"><strong>الموقع:</strong> {{ opportunity.location_en }}</p><p style="margin-left:0;">{% endif %}</p><p>يرجى تسجيل الدخول إلى منصة Forsa للتسجيل لهذه الفرصة في أقرب وقت ممكن.</p><p>شكراً لك على التفاني كصديق في Forsa!</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('112', '2025-12-04 16:12:36', '2026-03-12 12:34:45', 0, NULL, 'event_day_of_notification', 'فعاليتك اليوم!', '<p>عزيزي {{ user_name }},</p><p>فعاليتك &nbsp;<strong>{{ event_title }}</strong> يقام اليوم ({{ start_date }}).</p><p>شكرًا لانضمامك إلينا!</p><p>مع أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('111', '2025-12-04 16:12:36', '2026-03-12 12:34:56', 0, NULL, 'event_day_of_notification', 'Your Event is Today!', '<p>Dear {{ user_name }},</p><p>Your Event<strong> {{ event_title }}</strong> is happening today ({{ start_date }}).</p><p>Thank you for joining us!</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('2', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'contact_us_notification', 'إشعار اتصل بنا', '<p>عزيزي المشرف,</p>\n                    <p>لقد تلقيت طلب اتصال جديد منا.</p>\n                    <p><strong>الاسم:</strong> {{ name_en }}</p>\n                    <p><strong>البريد الإلكتروني:</strong> {{ email }}</p>\n                    <p><strong>الرسالة:</strong> {{ message_en }}</p>\n                    <p>أطيب التحيات,<br>فريق Forsa</p>', 'ar'),
('89', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'admin_user_ban_notification_low_attendance', 'User Temporarily Banned Due to Low Attendance', '<p>Hello Admin,</p>\n                    <p>A user has been temporarily banned from the platform for non-attendance.</p>\n                    <div style="margin: 20px 0; padding: 15px; border: 1px solid #eee; border-radius: 5px;">\n                        <p><strong>Banned User Details:</strong></p>\n                        <ul style="text-align: left; padding-left: 20px;">\n                            <li>Name: {{ banned_user_full_name }}</li>\n                            <li>Email: {{ banned_user.email }}</li>\n                            <li>Missed Opportunities: {{ non_attended_count }}</li>\n                            <li>Status: Temporarily Banned</li>\n                            <li>Duration: The ban will automatically lift after 1 month</li>\n                        </ul>\n                    </div>\n                    <p>Please review the user\'s account in the admin dashboard for any further action if necessary.</p>\n                    <p>Best regards,<br>The Volunteer System</p>', 'en'),
('62', '2025-12-04 16:12:36', '2026-03-12 12:52:41', 0, NULL, 'opportunity_deleted_notification', 'تم حذف الفرصة', '<p>عزيزي {{ user.get_full_name }},</p><p>نأسف لإعلامك بأنه تم حذف فرصة قمت بالتسجيل لها من قبل المنظم.</p><p style="margin-left:0;"><strong>الفرصة:</strong> {{ opportunity.title_en }}</p><p style="margin-left:0;"><strong>المنظم:</strong> {{ opportunity.created_by.get_full_name }}</p><p style="margin-left:0;"><strong>تم الحذف في:</strong> {{ deletion_date }}</p><p>إذا كانت لديك أي أسئلة، يرجى التواصل مع منظم الفرصة مباشرة.</p><p>نعتذر عن أي إزعاج قد يسببه هذا. يرجى التحقق من منصتنا للحصول على فرص أخرى متاحة تتناسب مع اهتماماتك.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('50', '2025-12-04 16:12:36', '2026-03-12 12:17:39', 0, NULL, 'learn_serve_unregistration_notification', 'إلغاء تسجيل', '<p>عزيزي {{ opportunity.created_by.get_full_name }},</p><p>قام مشارك بإلغاء التسجيل من فرصة تعلم وشارك الخاصة بك: <strong>{{ opportunity.title_en }}</strong></p><p style="margin-left:0;"><strong>اسم المشارك:</strong> {{ user.get_full_name }}</p><p style="margin-left:0;"><strong>البريد الإلكتروني:</strong> {{ user.email }}</p><p style="margin-left:0;"><strong>تم الإلغاء في:</strong> {{ unregistered_at }}</p><p>يمكنك مراجعة هذا التسجيل والتسجيلات الأخرى في لوحة التحكم الخاصة بك.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('10', '2025-12-04 16:12:36', '2026-03-12 12:49:18', 0, NULL, 'forbidden_words_reply_user_email', 'تم اكتشاف كلمات محظورة في ردك', '<p style="text-align:center;"><strong>مرحباً {{ user.first_name|default:"مستخدم" }},</strong></p><p style="text-align:center;">تم اكتشاف الكلمات المحظورة التالية في ردك:</p><p style="margin-left:0;">{% for word in detected_words %}</p><ul><li><p style="margin-left:0;text-align:center;">{{ word }}</p></li></ul><p style="margin-left:0;text-align:center;">{% endfor %}</p><p style="text-align:center;">نتيجة لذلك، لن يتم عرض ردك على المنصة.</p><p style="text-align:center;">إذا كانت لديك أي أسئلة، يرجى الاتصال بالدعم.</p><p style="text-align:center;">أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('1', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'contact_us_notification', 'Contact Us Notification', '<p>Dear Admin,</p>\n                    <p>You have received a new contact us request.</p>\n                    <p><strong>Name:</strong> {{ name_en }}</p>\n                    <p><strong>Email:</strong> {{ email }}</p>\n                    <p><strong>Message:</strong> {{ message_en }}</p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('102', '2025-12-04 16:12:36', '2026-03-12 12:50:21', 0, NULL, 'volunteer_completion_notification', 'شكرًا لك: تم الانتهاء من الفرصة التطوعية', '<p>عزيزي {{ user_name }},</p><p>شكرًا لمشاركتك في الفرصة التطوعية <strong>{{ opportunity_title }}</strong> التي انتهت في {{ end_date }}.</p><p>نحن نقدر جهودك ومساهمتك!</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('22', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'new_sponsor_admin_notification', 'تمت إضافة راعٍ جديد', '<p>عزيزي المشرف,</p>\n                    <p>تمت إضافة راعٍ جديد إلى منصة Forsa.</p>\n                    <div style="margin: 20px 0; padding: 15px; border: 1px solid #eee; border-radius: 5px;">\n                        <h3 style="margin-top: 0;">تفاصيل الراعي:</h3>\n                        <p><strong>اسم المنظمة:</strong> {{ sponsor.name_en }}</p>\n                        {% if sponsor.email %}\n                        <p><strong>البريد الإلكتروني:</strong> {{ sponsor.email }}</p>\n                        {% endif %}\n                        {% if sponsor.phone_number %}\n                        <p><strong>الهاتف:</strong> {{ sponsor.phone_number }}</p>\n                        {% endif %}\n                        {% if sponsor.sponsor_type_name %}\n                        <p><strong>نوع الرعاية:</strong> {{ sponsor.sponsor_type_name }}</p>\n                        {% endif %}\n                    </div>\n                    <p>يرجى النقر على الرابط أدناه لعرض التفاصيل واتخاذ الإجراء:</p>\n                    <p><a href="{{ deep_link }}">عرض التفاصيل</a></p>\n                    <p>أطيب التحيات,<br>فريق Forsa</p>', 'ar'),
('76', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'event_deletion_request_admin', 'طلب حذف الحدث', '<p>عزيزي المشرف,</p>\n                    <p>تم تقديم طلب حذف للحدث: <strong>{{ event.title_en }}</strong>.</p>\n                    <div style="background-color: #f9f9f9; padding: 15px; border-radius: 8px; margin: 15px 0; text-align: left;">\n                        <p style="margin-top: 0;"><strong>عنوان الحدث:</strong> {{ event.title_en }}</p>\n                        <p><strong>أنشأه:</strong> {{ event.created_by.user.get_full_name }}</p>\n                        <p><strong>بريد المنشئ:</strong> {{ event.created_by.user.email }}</p>\n                        <p><strong>تاريخ البدء:</strong> {{ event.start_date }}</p>\n                        <p><strong>تاريخ الانتهاء:</strong> {{ event.end_date }}</p>\n                        <p><strong>تاريخ الاستحقاق:</strong> {{ event.due_date }}</p>\n                        <p><strong>تاريخ الطلب:</strong> {{ request_date }}</p>\n                        <p style="margin-bottom: 0;"><strong>سبب الطلب:</strong> {{ reason|default:"لم يتم تقديم سبب" }}</p>\n                    </div>\n                    <p>يرجى النقر على الرابط أدناه لعرض التفاصيل واتخاذ الإجراء:</p>\n                    <p><a href="{{ deep_link }}">عرض التفاصيل</a></p>\n                    <p>أطيب التحيات,<br>فريق Forsa</p>', 'ar'),
('39', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'volunteer_registration_creator_notification', 'New Volunteer Registration', '<p>Hello {{ opportunity.created_by.first_name }},</p>\n                    <p>A new volunteer has registered for your opportunity: <strong>{{ opportunity.title_en }}</strong></p>\n                    <div style="margin: 20px 0; padding: 15px; border: 1px solid #eee; border-radius: 5px;">\n                        <p><strong>Volunteer details:</strong></p>\n                        <ul style="text-align: left; padding-left: 20px;">\n                            <li>Name: {{ volunteer.get_full_name }}</li>\n                            <li>Email: {{ volunteer.email }}</li>\n                            <li>Registration time: {{ registration_time }}</li>\n                        </ul>\n                    </div>\n                    <p>You can view all registrations for this opportunity in your dashboard.</p>\n                    <p>Thank you for creating opportunities with Forsa!</p>', 'en'),
('51', '2025-12-04 16:12:36', '2026-03-12 12:15:50', 0, NULL, 'learn_serve_registration_creator_notification', 'New Registration', '<p>Hello {{ opportunity.created_by.first_name }},</p><p>A new attendee has registered for your Learn &amp; Share opportunity: <strong>{{ opportunity.title_en }}</strong></p><p style="margin-left:0;"><strong>Attendee details:</strong></p><ul><li><p style="margin-left:0;">Name: {{ attendee.get_full_name }}</p></li><li><p style="margin-left:0;">Email: {{ attendee.email }}</p></li><li><p style="margin-left:0;">Registration time: {{ registration_time }}</p></li></ul><p>You can view all registrations for this opportunity in your dashboard.</p><p>Thank you for creating opportunities with Forsa!</p>', 'en'),
('15', '2025-12-04 16:12:36', '2026-01-19 06:21:19', 0, NULL, 'contact_post_creator_email', 'Message Regarding Your Post', '\n                <p>Dear {{ post.user.first_name }},</p>\n                <p>You have received a message regarding your post from {{ sender.get_full_name }}.</p>\n                <p>Message:</p>\n                <p><i>{{ message }}</i></p>\n                <p>You can reply to this email to contact the sender directly.</p>\n            ', 'en'),
('106', '2025-12-04 16:12:36', '2026-03-12 12:22:08', 0, NULL, 'learnserve_day_of_notification', 'تذكير : اليوم هو موعد الفرصة', '<p>عزيزي {{ user_name }},</p><p>فرصة &nbsp;<strong>{{ opportunity_title }}</strong> تبدأ اليوم ({{ start_date }}).</p><p>يسعدنا انضمامك إلينا.</p><p>مع أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('100', '2025-12-04 16:12:36', '2026-03-12 12:29:39', 0, NULL, 'volunteer_day_of_notification', 'تذكير : اليوم هو موعد الفرصة التطوعية', '<p>عزيزي {{ user_name }},</p><p>الفرصة التطوعية الخاصة بك <strong>{{ opportunity_title }}</strong> تقام اليوم ({{ start_date }}).</p><p>شكرًا لكونك جزءًا من هذه التجربة.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('99', '2025-12-04 16:12:36', '2026-03-12 12:30:04', 0, NULL, 'volunteer_day_of_notification', 'Reminder: Today is the day of opportunity.', '<p>Dear {{ user_name }},</p><p>Your volunteer opportunity <strong>{{ opportunity_title }}</strong> is happening today ({{ start_date }}).</p><p>Thank you for being part of this journey.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('16', '2025-12-04 16:12:36', '2026-01-19 06:21:19', 0, NULL, 'contact_post_creator_email', 'رسالة بخصوص منشورك', '\n                <p>عزيزي {{ post.user.first_name }},</p>\n                <p>لقد تلقيت رسالة بخصوص منشورك من {{ sender.get_full_name }}.</p>\n                <p>الرسالة:</p>\n                <p><i>{{ message }}</i></p>\n                <p>يمكنك الرد على هذا البريد الإلكتروني للاتصال بالمرسل مباشرة.</p>\n            ', 'ar'),
('4', '2025-12-04 16:12:36', '2026-03-12 12:48:22', 0, NULL, 'account_activation_email', 'تفعيل حسابك', '<p>عزيزي {{ user.first_name }},</p><p>شكراً لك على التسجيل في Forsa.</p><p>استخدم رمز OTP أدناه لإكمال عملية التحقق:</p><p>{{ otp_code }}</p><p>هذا {{method|lower}} صالح لمدة {{ expiry_time }} دقائق.</p><p>إذا لم تقم بالتسجيل، يرجى تجاهل هذا البريد الإلكتروني.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('3', '2025-12-04 16:12:36', '2026-03-12 12:48:29', 0, NULL, 'account_activation_email', 'Activate Your Account', '<p>Dear {{ user.first_name }},</p><p>Thank you for registering with Forsa.</p><p>Use the below OTP code to complete your verification process:</p><p>{{ otp_code }}</p><p>This {{method|lower}} is valid for {{ expiry_time }} minutes.</p><p>If you did not register, please ignore this email.</p><p>Best regards,<br>Forsa Team</p>', 'en'),
('120', '2026-01-19 06:21:16', '2026-01-19 06:21:18', 0, NULL, 'admin_notification_new_entity', 'New Entity Registered', '<p>Dear Admin,</p>\n                    <p>A new entity has been registered on the platform.</p>\n                    <p><strong>Entity Name:</strong> {{ entity_name }}</p>\n                    <p>Please click the link below to view details and take action:</p>\n                    <p><a href="{{ deep_link }}">View Details</a></p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('119', '2026-01-19 06:21:16', '2026-01-19 06:21:18', 0, NULL, 'admin_notification_new_entity', 'تم تسجيل كيان جديد', '<p>عزيزي المشرف,</p>\n                    <p>تم تسجيل كيان جديد على المنصة.</p>\n                    <p><strong>اسم الكيان:</strong> {{ entity_name }}</p>\n                    <p>يرجى النقر على الرابط أدناه لعرض التفاصيل واتخاذ الإجراء:</p>\n                    <p><a href="{{ deep_link }}">عرض التفاصيل</a></p>\n                    <p>أطيب التحيات,<br>فريق Forsa</p>', 'ar'),
('124', '2026-01-19 06:21:16', '2026-01-19 06:21:18', 0, NULL, 'admin_notification_new_opportunity', 'New Initiative Submitted', '<p>Dear Admin,</p>\n                    <p>A new opportunity has been submitted for approval.</p>\n                    <p><strong>Opportunity Name:</strong> {{ opportunity_name }}</p>\n                    <p>Please click the link below to view details and take action:</p>\n                    <p><a href="{{ deep_link }}">View Details</a></p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('123', '2026-01-19 06:21:16', '2026-01-19 06:21:18', 0, NULL, 'admin_notification_new_opportunity', 'تم تقديم مبادرة جديدة', '<p>عزيزي المشرف,</p>\n                    <p>تم تقديم فرصة جديدة للموافقة عليها.</p>\n                    <p><strong>اسم الفرصة:</strong> {{ opportunity_name }}</p>\n                    <p>يرجى النقر على الرابط أدناه لعرض التفاصيل واتخاذ الإجراء:</p>\n                    <p><a href="{{ deep_link }}">عرض التفاصيل</a></p>\n                    <p>أطيب التحيات,<br>فريق Forsa</p>', 'ar'),
('122', '2026-01-19 06:21:16', '2026-01-19 06:21:18', 0, NULL, 'admin_notification_new_event', 'New Initiative Submitted', '<p>Dear Admin,</p>\n                    <p>A new event has been submitted for approval.</p>\n                    <p><strong>Event Name:</strong> {{ event_name }}</p>\n                    <p>Please click the link below to view details and take action:</p>\n                    <p><a href="{{ deep_link }}">View Details</a></p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('37', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'event_rejection_email', 'Event Rejected', '<p>Dear {{ user.first_name }},</p>\n                    <p>We regret to inform you that your event "<b>{{ event_title }}</b>" has been rejected.</p>\n                    <p>Reason: <b>{{ rejection_reason }}</b></p>\n                    <p>If you have any questions, please feel free to contact us.</p>', 'en'),
('36', '2025-12-04 16:12:36', '2026-03-12 12:31:58', 0, NULL, 'event_approval_email', 'تمت الموافقة على الفعالية', '<p>عزيزي {{ user.first_name }},</p><p>يسعدنا إعلامك بأنه تم الموافقة على &nbsp;"<strong>{{ event_title }}</strong>".</p><p>شكراً لك على مساهمتك!</p>', 'ar'),
('35', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'event_approval_email', 'Event Approved', '<p>Dear {{ user.first_name }},</p>\n                    <p>We are pleased to inform you that your event "<b>{{ event_title }}</b>" has been approved.</p>\n                    <p>Thank you for your contribution!</p>', 'en'),
('7', '2025-12-04 16:12:36', '2026-03-12 12:47:49', 0, NULL, 'forbidden_words_user_email', 'Forbidden Words Detected in Your Post', '<p>Hello {{ user.first_name }},</p><p>The following forbidden words were detected in your post "<strong>{{ post_title }}</strong>":</p><p>{% for word in detected_words %}</p><ul><li>{{ word }}</li></ul><p>{% endfor %}</p><p>As a result, your post will not be displayed on the platform.</p><p>Best regards,<br>Forsa Team</p>', 'en'),
('17', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'sponsor_approval_email', 'Sponsorship Application Approved', '<p>Dear {{ sponsor.person_name }},</p>\n                    <p>We are delighted to inform you that your sponsorship application has been approved.</p>\n                    <p>Thank you for your support and contribution to our platform. We look forward to working with you.</p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('5', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'forgot_password', 'Reset Your Password', '<p>Hi {{ user.first_name }},</p>\n                    <p>You requested to reset your password.</p>\n                    <p>Use the below OTP code to reset your password:</p\n                    <p>{{ otp_code }}</p>\n                    <p>This {{method|lower}} is valid for {{ expiry_time }} minutes.</p>\n                    <p>If you didn\'t request a password reset, please ignore this email.</p>', 'en'),
('6', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'forgot_password', 'إعادة تعيين كلمة المرور', '<p>مرحباً {{ user.first_name }},</p>\n                    <p>لقد طلبت إعادة تعيين كلمة المرور الخاصة بك.</p>\n                    <p>استخدم رمز OTP أدناه لإعادة تعيين كلمة المرور:</p>\n                    <p>{{ otp_code }}</p>\n                    <p>هذا {{method|lower}} صالح لمدة {{ expiry_time }} دقائق.</p>\n                    <p>إذا لم تطلب إعادة تعيين كلمة المرور، يرجى تجاهل هذا البريد الإلكتروني.</p>', 'ar'),
('11', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'forbidden_words_reply_admin_email', 'Forbidden Words Detected in a Reply', '<p style="text-align: center; font-size: 18px; font-weight: bold; color: #333;">Hello Admin,</p>\n                    <p style="text-align: center; font-size: 16px; color: #555;">The following forbidden words were detected in a reply created by {{ user.get_full_name }} ({{ user.email }}):</p>\n                    <div style="display: flex; justify-content: center; align-items: center; flex-direction: column; margin: 20px 0;">\n                        <ul style="list-style: none; padding: 0; margin: 0; text-align: center; width: 100%; max-width: 400px;">\n                            {% for word in detected_words %}\n                            <li style="padding: 5px; border-bottom: 0px solid #ddd; font-size: 16px; color: #333;">{{ word }}</li>\n                            {% endfor %}\n                        </ul>\n                    </div>\n                    <p style="text-align: center; font-size: 16px; color: #555;">As a result, the reply will not be displayed on the platform.</p>\n                    <p style="text-align: center; font-size: 16px; color: #555;">Best regards,<br><strong>The Volunteer Team</strong></p>', 'en'),
('12', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'forbidden_words_reply_admin_email', 'تم اكتشاف كلمات محظورة في رد', '<p style="text-align: center; font-size: 18px; font-weight: bold; color: #333;">مرحباً المشرف,</p>\n                    <p style="text-align: center; font-size: 16px; color: #555;">تم اكتشاف الكلمات المحظورة التالية في رد أنشأه {{ user.get_full_name }} ({{ user.email }}):</p>\n                    <div style="display: flex; justify-content: center; align-items: center; flex-direction: column; margin: 20px 0;">\n                        <ul style="list-style: none; padding: 0; margin: 0; text-align: center; width: 100%; max-width: 400px;">\n                            {% for word in detected_words %}\n                            <li style="padding: 5px; border-bottom: 0px solid #ddd; font-size: 16px; color: #333;">{{ word }}</li>\n                            {% endfor %}\n                        </ul>\n                    </div>\n                    <p style="text-align: center; font-size: 16px; color: #555;">نتيجة لذلك، لن يتم عرض الرد على المنصة.</p>\n                    <p style="text-align: center; font-size: 16px; color: #555;">أطيب التحيات,<br><strong>فريق المتطوعين</strong></p>', 'ar'),
('13', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'forbidden_words_admin_email', 'Forbidden Words Detected in a Post', '<p>Hello Admin,</p>\n                    <p>The following forbidden words were detected in a post titled "<strong>{{ post_title }}</strong>" created by {{ user.get_full_name }}:</p>\n                    <ul>\n                        {% for word in detected_words %}\n                        <li>{{ word }}</li>\n                        {% endfor %}\n                    </ul>\n                    <p>As a result, the post will not be displayed on the platform.</p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('19', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'sponsor_rejection_email', 'Sponsorship Application Rejected', '<p>Dear {{ sponsor.person_name }},</p>\n                    <p>We regret to inform you that your sponsorship application has been rejected.</p>\n                    <p><b>Reason:</b> {{ rejection_reason }}</p>\n                    <p>If you have any questions, please feel free to contact us.</p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('21', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'new_sponsor_admin_notification', 'New Sponsor Added', '<p>Dear Admin,</p>\n                    <p>A new sponsor has been added to the Forsa platform.</p>\n                    <div style="margin: 20px 0; padding: 15px; border: 1px solid #eee; border-radius: 5px;">\n                        <h3 style="margin-top: 0;">Sponsor Details:</h3>\n                        <p><strong>Organization Name:</strong> {{ sponsor.name_en }}</p>\n                        {% if sponsor.email %}\n                        <p><strong>Email:</strong> {{ sponsor.email }}</p>\n                        {% endif %}\n                        {% if sponsor.phone_number %}\n                        <p><strong>Phone:</strong> {{ sponsor.phone_number }}</p>\n                        {% endif %}\n                        {% if sponsor.sponsor_type_name %}\n                        <p><strong>Sponsor Type:</strong> {{ sponsor.sponsor_type_name }}</p>\n                        {% endif %}\n                    </div>\n                    <p>Please click the link below to view details and take action:</p>\n                    <p><a href="{{ deep_link }}">View Details</a></p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('8', '2025-12-04 16:12:36', '2026-03-12 12:49:22', 0, NULL, 'forbidden_words_user_email', 'تم اكتشاف كلمات محظورة في منشورك', '<p>مرحباً {{ user.first_name }},</p><p>تم اكتشاف الكلمات المحظورة التالية في منشورك "<strong>{{ post_title }}</strong>":</p><p>{% for word in detected_words %}</p><ul><li>{{ word }}</li></ul><p>{% endfor %}</p><p>نتيجة لذلك، لن يتم عرض منشورك على المنصة.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('18', '2025-12-04 16:12:36', '2026-03-12 12:49:37', 0, NULL, 'sponsor_approval_email', 'تمت الموافقة على طلب الرعاية', '<p>عزيزي {{ sponsor.person_name }},</p><p>يسعدنا إعلامك بأنه تم الموافقة على طلب رعايتك.</p><p>شكراً لك على دعمك ومساهمتك في منصتنا. نتطلع إلى العمل معك.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('20', '2025-12-04 16:12:36', '2026-03-12 12:49:40', 0, NULL, 'sponsor_rejection_email', 'تم رفض طلب الرعاية', '<p>عزيزي {{ sponsor.person_name }},</p><p>نأسف لإعلامك بأنه تم رفض طلب رعايتك.</p><p><strong>السبب:</strong> {{ rejection_reason }}</p><p>إذا كانت لديك أي أسئلة، يرجى التواصل معنا.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('137', '2026-01-19 06:21:18', '2026-01-19 06:21:18', 0, NULL, 'volunteer_opportunity_approval_email', 'Volunteer Opportunity Approved', '<p>Dear {{ user.first_name }},</p>\n                    <p>We are pleased to inform you that your volunteer opportunity "<b>{{ opportunity_title }}</b>" has been approved.</p>\n                    <p>Thank you for your contribution!</p>', 'en'),
('138', '2026-01-19 06:21:18', '2026-01-19 06:21:18', 0, NULL, 'volunteer_opportunity_approval_email', 'تمت الموافقة على فرصة التطوع', '<p>عزيزي {{ user.first_name }},</p>\n                    <p>يسعدنا إعلامك بأنه تم الموافقة على فرصة التطوع الخاصة بك "<b>{{ opportunity_title }}</b>".</p>\n                    <p>شكراً لك على مساهمتك!</p>', 'ar'),
('29', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'opportunity_rejection_email', 'Opportunity Rejected', '<p>Dear {{ user.first_name }},</p>\n                    <p>We regret to inform you that your opportunity "<b>{{ opportunity_title }}</b>" has been rejected.</p>\n                    <p><b>Reason:</b> {{ rejection_reason }}</p>\n                    <p>If you have any questions, please feel free to contact us.</p>', 'en'),
('30', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'opportunity_rejection_email', 'تم رفض الفرصة', '<p>عزيزي {{ user.first_name }},</p>\n                    <p>نأسف لإعلامك بأنه تم رفض فرصتك "<b>{{ opportunity_title }}</b>".</p>\n                    <p><b>السبب:</b> {{ rejection_reason }}</p>\n                    <p>إذا كانت لديك أي أسئلة، يرجى التواصل معنا.</p>', 'ar'),
('121', '2026-01-19 06:21:16', '2026-01-19 06:21:18', 0, NULL, 'admin_notification_new_event', 'تم تقديم مبادرة جديدة', '<p>عزيزي المشرف,</p>\n                    <p>تم تقديم حدث جديد للموافقة عليه.</p>\n                    <p><strong>اسم الحدث:</strong> {{ event_name }}</p>\n                    <p>يرجى النقر على الرابط أدناه لعرض التفاصيل واتخاذ الإجراء:</p>\n                    <p><a href="{{ deep_link }}">عرض التفاصيل</a></p>\n                    <p>أطيب التحيات,<br>فريق Forsa</p>', 'ar'),
('33', '2025-12-04 16:12:36', '2026-03-12 12:26:18', 0, NULL, 'learn_serve_update_notification', 'Opportunity Updated', '<p>Dear {{ user.get_full_name }},</p><p>Your registered opportunity "<strong>{{ opportunity.title_en }}</strong>" has been updated.</p><p>Please log in to your account to view the complete details.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('34', '2025-12-04 16:12:36', '2026-03-12 12:12:16', 0, NULL, 'learn_serve_update_notification', 'تحديث فرصة', '<p>عزيزي {{ user.get_full_name }},</p><p>تم تحديث فرصتك المسجلة &nbsp;"<strong>{{ opportunity.title_en }}</strong>".</p><p>يرجى تسجيل الدخول إلى حسابك لعرض التفاصيل الكاملة.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('140', '2026-01-19 06:21:18', '2026-03-12 12:19:29', 0, NULL, 'learn_share_opportunity_approval_email', 'تمت الموافقة على نشر الفرصة', '<p>عزيزي {{ user.first_name }},</p><p>يسعدنا إعلامك بأنه تم الموافقة على فرصة تعلم وشارك الخاصة بك "<strong>{{ opportunity_title }}</strong>".</p><p>شكراً لك على مساهمتك!</p>', 'ar'),
('139', '2026-01-19 06:21:18', '2026-03-12 12:19:31', 0, NULL, 'learn_share_opportunity_approval_email', 'Approval to publish the opportunity', '<p>Dear {{ user.first_name }},</p><p>We are pleased to inform you that your Learn &amp; Share opportunity "<strong>{{ opportunity_title }}</strong>" has been approved.</p><p>Thank you for your contribution!</p>', 'en'),
('31', '2025-12-04 16:12:36', '2026-03-12 12:42:51', 0, NULL, 'opportunity_update_notification', 'Opportunity Updated', '<p>Dear {{ user.get_full_name }},</p><p>Your registered opportunity "<strong>{{ opportunity.title_en }}</strong>" has been updated.</p><p>Please log in to your account to view the complete details.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('23', '2025-12-04 16:12:36', '2026-03-12 12:47:01', 0, NULL, 'entity_profile_approval', 'Entity account Approved', '<p>Dear {{ user.first_name }},</p><p>We are delighted to inform you that your entity account "<strong>{{ organization_name }}</strong>" has been successfully approved.</p><p>Thank you for your efforts and contribution to our platform. We look forward to your continued engagement.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('32', '2025-12-04 16:12:36', '2026-03-12 12:52:51', 0, NULL, 'opportunity_update_notification', 'تم تحديث الفرصة', '<p>عزيزي {{ user.get_full_name }},</p><p>تم تحديث فرصتك المسجلة "<strong>{{ opportunity.title_en }}</strong>".</p><p>يرجى تسجيل الدخول إلى حسابك لعرض التفاصيل الكاملة.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('45', '2025-12-04 16:12:36', '2026-03-12 12:28:03', 0, NULL, 'volunteer_bulk_registration_notification', 'Bulk Volunteer Registration', '<p>Dear {{ user.get_full_name }},</p><p>You have been registered for the following volunteer opportunity by the opportunity owner:</p><p style="margin-left:0;"><strong>Opportunity:</strong> {{ opportunity.title_en }}</p><p style="margin-left:0;"><strong>Organizer:</strong> {{ opportunity.created_by.get_full_name }}</p><p style="margin-left:0;"><strong>Registered on:</strong> {{ registered_at }}</p><p style="margin-left:0;">{% if opportunity.link %}</p><p style="margin-left:0;"><strong>Event Link:</strong> <a href="{{ opportunity.link }}">{{ opportunity.link }}</a></p><p style="margin-left:0;">{% endif %}</p><p>You can find more details about this opportunity in your dashboard. If you have any questions, please contact the opportunity organizer.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('46', '2025-12-04 16:12:36', '2026-03-12 12:50:15', 0, NULL, 'volunteer_bulk_registration_notification', 'تسجيل جماعي للمتطوعين', '<p>عزيزي {{ user.get_full_name }},</p><p>لقد تم تسجيلك لفرصة التطوع التالية من قبل مالك الفرصة:</p><p style="margin-left:0;"><strong>الفرصة:</strong> {{ opportunity.title_en }}</p><p style="margin-left:0;"><strong>المنظم:</strong> {{ opportunity.created_by.get_full_name }}</p><p style="margin-left:0;"><strong>تم التسجيل في:</strong> {{ registered_at }}</p><p style="margin-left:0;">{% if opportunity.link %}</p><p style="margin-left:0;"><strong>رابط الحدث:</strong> <a href="{{ opportunity.link }}">{{ opportunity.link }}</a></p><p style="margin-left:0;">{% endif %}</p><p>يمكنك العثور على المزيد من التفاصيل حول هذه الفرصة في لوحة التحكم الخاصة بك. إذا كانت لديك أي أسئلة، يرجى التواصل مع منظم الفرصة.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('48', '2025-12-04 16:12:36', '2026-03-12 12:50:18', 0, NULL, 'volunteer_bulk_unregistration_notification', 'إلغاء تسجيل جماعي للمتطوعين', '<p>عزيزي {{ user.get_full_name }},</p><p>لقد تم إلغاء تسجيلك من فرصة التطوع التالية من قبل مالك الفرصة:</p><p style="margin-left:0;"><strong>الفرصة:</strong> {{ opportunity.title_en }}</p><p style="margin-left:0;"><strong>المنظم:</strong> {{ opportunity.created_by.get_full_name }}</p><p style="margin-left:0;"><strong>تم الإلغاء في:</strong> {{ unregistered_at }}</p><p>إذا كانت لديك أي أسئلة، يرجى التواصل مع منظم الفرصة.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('42', '2025-12-04 16:12:36', '2026-03-12 12:50:29', 0, NULL, 'volunteer_registration_confirmation', 'تأكيد تسجيل المتطوع', '<p>عزيزي {{ user.get_full_name }},</p><p>شكراً لك على التسجيل لفرصة التطوع: <strong>{{ opportunity.title_en }}</strong>.</p><h3 style="margin-left:0;">تفاصيل الفرصة:</h3><p style="margin-left:0;"><strong>التاريخ:</strong> {{ opportunity.start_date|date:"F j, Y" }} {% if opportunity.end_date and opportunity.end_date != opportunity.start_date %} إلى {{ opportunity.end_date|date:"F j, Y" }} {% endif %}</p><p style="margin-left:0;">{% if opportunity.start_time and opportunity.end_time %}</p><p style="margin-left:0;"><strong>الوقت:</strong> {{ opportunity.start_time|time:"g:i A" }} - {{ opportunity.end_time|time:"g:i A" }}</p><p style="margin-left:0;">{% endif %} {% if opportunity.location_en %}</p><p style="margin-left:0;"><strong>الموقع:</strong> {{ opportunity.location_en }}</p><p style="margin-left:0;">{% endif %}</p><p>{% if link %}</p><p>يمكنك الانضمام عبر WhatsApp باستخدام الرابط أدناه:</p><p><a href="{{ link }}">{{ link }}</a></p><p>{% endif %}</p><p>يسعدنا انضمامك إلينا. يرجى التواصل معنا إذا كانت لديك أي أسئلة.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('55', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'opportunity_deletion_request_admin', 'Opportunity Deletion Request', '<p>Dear Admin,</p>\n                    <p>A user has requested to delete an opportunity: <strong>{{ opportunity.title_en }}</strong></p>\n                    <div style="background-color: #f9f9f9; padding: 15px; border-radius: 8px; margin: 15px 0; text-align: left;">\n                        <p style="margin-top: 0;"><strong>Opportunity Title:</strong> {{ opportunity.title_en }}</p>\n                        <p><strong>Created By:</strong> {{ opportunity.created_by.get_full_name }}</p>\n                        <p><strong>Creator Email:</strong> {{ opportunity.created_by.email }}</p>\n                        <p><strong>Due Date:</strong> {{ opportunity.due_date }}</p>\n                        <p><strong>Request Date:</strong> {{ request_date }}</p>\n                        <p style="margin-bottom: 0;"><strong>Request Reason:</strong> {{ reason|default:"No reason provided" }}</p>\n                    </div>\n                    <p>Please click the link below to view details and take action:</p>\n                    <p><a href="{{ deep_link }}">View Details</a></p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('56', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'opportunity_deletion_request_admin', 'طلب حذف الفرصة', '<p>عزيزي المشرف,</p>\n                    <p>طلب مستخدم حذف فرصة: <strong>{{ opportunity.title_en }}</strong></p>\n                    <div style="background-color: #f9f9f9; padding: 15px; border-radius: 8px; margin: 15px 0; text-align: left;">\n                        <p style="margin-top: 0;"><strong>عنوان الفرصة:</strong> {{ opportunity.title_en }}</p>\n                        <p><strong>أنشأها:</strong> {{ opportunity.created_by.get_full_name }}</p>\n                        <p><strong>بريد المنشئ:</strong> {{ opportunity.created_by.email }}</p>\n                        <p><strong>تاريخ الاستحقاق:</strong> {{ opportunity.due_date }}</p>\n                        <p><strong>تاريخ الطلب:</strong> {{ request_date }}</p>\n                        <p style="margin-bottom: 0;"><strong>سبب الطلب:</strong> {{ reason|default:"لم يتم تقديم سبب" }}</p>\n                    </div>\n                    <p>يرجى النقر على الرابط أدناه لعرض التفاصيل واتخاذ الإجراء:</p>\n                    <p><a href="{{ deep_link }}">عرض التفاصيل</a></p>\n                    <p>أطيب التحيات,<br>فريق Forsa</p>', 'ar'),
('53', '2025-12-04 16:12:36', '2026-03-12 12:26:03', 0, NULL, 'learn_serve_registration_confirmation', 'Registration Confirmation', '<p>Dear {{ user.get_full_name }},</p><p>Thank you for registering for opportunity: <strong>{{ opportunity.title_en }}</strong>.</p><h3 style="margin-left:0;">Opportunity Details:</h3><p style="margin-left:0;"><strong>Date:</strong> {{ opportunity.start_date|date:"F j, Y" }} {% if opportunity.end_date and opportunity.end_date != opportunity.start_date %} to {{ opportunity.end_date|date:"F j, Y" }} {% endif %}</p><p style="margin-left:0;">{% if opportunity.start_time and opportunity.end_time %}</p><p style="margin-left:0;"><strong>Time:</strong> {{ opportunity.start_time|time:"g:i A" }} - {{ opportunity.end_time|time:"g:i A" }}</p><p style="margin-left:0;">{% endif %} {% if opportunity.location_en %}</p><p style="margin-left:0;"><strong>Location:</strong> {{ opportunity.location_en }}</p><p style="margin-left:0;">{% endif %}</p><p>{% if link %}</p><p>You can join the meeting using the link below:</p><p><a href="{{ link }}">{{ link }}</a></p><p>{% endif %}</p><p>We are excited to have you join us. Please feel free to reach out if you have any questions.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('57', '2025-12-04 16:12:36', '2026-03-12 12:42:33', 0, NULL, 'opportunity_deletion_rejected', 'Opportunity Deletion Rejected', '<p><strong>{{ user.get_full_name }}</strong></p><p>Your request to delete the opportunity&nbsp;</p><p><strong>{{ opportunity.title_en }}</strong> has been rejected.</p><p style="margin-left:0;"><strong>Opportunity Title:</strong> {{ opportunity.title_en }}</p><p style="margin-left:0;"><strong>Rejection Date:</strong> {{ rejection_date }}</p><p style="margin-left:0;">{% if rejection_reason %}</p><p style="margin-left:0;"><strong>Reason for Rejection:</strong> {{ rejection_reason }}</p><p style="margin-left:0;">{% endif %}</p><p>If you have any questions or need further clarification, please contact our support team.</p><p>Best wishes<br>Forsa Team</p>', 'en'),
('63', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'fursa_friend_backup_notification', 'Forsa Friend Backup Needed', '<p>Dear {{ friend.user.get_full_name }},</p>\n                    <p><strong>URGENT:</strong> Volunteer opportunity \'<strong>{{ opportunity.title_en }}</strong>\' needs additional volunteers.</p>\n                    <div style="margin: 20px 0; padding: 15px; border: 1px solid #eee; border-radius: 5px; background-color: #fff9f9;">\n                        <h3 style="margin-top: 0; color: #e53e3e;">Backup Support Needed</h3>\n                        <p>As a valued Forsa Friend, your help is urgently needed to support this volunteer opportunity regardless of skills or interests.</p>\n                        <p><strong>Volunteers needed:</strong> {{ volunteers_needed }} more</p>\n                        <h4 style="margin-top: 15px;">Opportunity Details:</h4>\n                        <p><strong>Date:</strong> {{ opportunity.start_date|date:"F j, Y" }}\n                            {% if opportunity.end_date and opportunity.end_date != opportunity.start_date %}\n                            to {{ opportunity.end_date|date:"F j, Y" }}\n                            {% endif %}\n                        </p>\n                        {% if opportunity.start_time and opportunity.end_time %}\n                        <p><strong>Time:</strong> {{ opportunity.start_time|time:"g:i A" }} - {{ opportunity.end_time|time:"g:i A" }}</p>\n                        {% endif %}\n                        {% if opportunity.location_en %}\n                        <p><strong>Location:</strong> {{ opportunity.location_en }}</p>\n                        {% endif %}\n                    </div>\n                    <p>Please log in to the Forsa platform to register for this opportunity as soon as possible.</p>\n                    <p>Thank you for your dedication as a Forsa Friend!</p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('65', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'fursa_friend_added', 'Welcome to Forsa Friends', '<p>Dear {% if user.get_full_name %}{{ user.get_full_name }}{% else %}{{ user.email }}{% endif %},</p>\n                    <p>Congratulations! You have been added to the <strong>Forsa Friends</strong> by {% with admin_name=added_by.get_full_name %}{% if admin_name %}{{ admin_name }}{% else %}{{ added_by.email }}{% endif %}{% endwith %}.</p>\n                    <p>We\'re excited to have you as part of our community. We look forward to your participation and contributions!</p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('66', '2025-12-04 16:12:36', '2026-03-12 12:52:26', 0, NULL, 'fursa_friend_added', 'مرحباً بك في أصدقاء Forsa', '<p>عزيزي {% if user.get_full_name %}{{ user.get_full_name }}{% else %}{{ user.email }}{% endif %},</p><p>تهانينا! لقد تمت إضافتك إلى <strong>أصدقاء Forsa</strong> من قبل {% with admin_name=added_by.get_full_name %}{% if admin_name %}{{ admin_name }}{% else %}{{ added_by.email }}{% endif %}{% endwith %}.</p><p>يسعدنا انضمامك إلى مجتمعنا. نتطلع إلى مشاركتك ومساهماتك!</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('59', '2025-12-04 16:12:36', '2026-03-12 12:42:24', 0, NULL, 'opportunity_deletion_approved', 'Opportunity Deletion Approved', '<p><strong>{{ user.get_full_name }}</strong></p><p>Your request to delete the opportunity</p><p><strong>{{ opportunity.title_en }}</strong></p><p>has been approved and the opportunity has been successfully removed.</p><p style="margin-left:0;"><strong>Opportunity Title:</strong> {{ opportunity.title_en }}</p><p style="margin-left:0;"><strong>Approval Date:</strong> {{ approval_date }}</p><p>Thank you for using our platform.</p><p>Best wishes<br>Forsa Team</p>', 'en'),
('58', '2025-12-04 16:12:36', '2026-03-12 12:52:47', 0, NULL, 'opportunity_deletion_rejected', 'تم رفض حذف الفرصة', '<p><strong>{{ user.get_full_name }}</strong></p><p>&nbsp;لقد تم رفض طلبك لحذف الفرصة&nbsp;</p><p>&nbsp;<strong>{{ opportunity.title_en }}</strong></p><p style="margin-left:0;">&nbsp;{{ opportunity.title_en }} <strong>:عنوان الفرصة</strong></p><p style="margin-left:0;">&nbsp;{{ rejection_date }} <strong>:تاريخ الرفض</strong></p><p style="margin-left:0;">{% if rejection_reason %}</p><p style="margin-left:0;">&nbsp;{{ rejection_reason }} <strong>:سبب الرفض</strong></p><p style="margin-left:0;">{% endif %}</p><p>إذا كانت لديك أي أسئلة أو كنت بحاجة إلى توضيحات إضافية، يرجى التواصل مع فريق الدعم لدينا.</p><p>مع اطيب التمنيات<br>فريق فرصة</p>', 'ar'),
('78', '2025-12-04 16:12:36', '2026-03-12 12:38:00', 0, NULL, 'event_deletion_rejected', 'تم رفض حذف الفعالية', '<p>عزيزي {{ user.get_full_name }},</p><p>لقد تم رفض طلب حذف الفعالية:</p><p style="margin-left:0;"><strong>الفعالية:</strong> {{ event.title_en }}</p><p style="margin-left:0;"><strong>تاريخ الطلب:</strong> {{ request_date }}</p><p style="margin-left:0;"><strong>تم الرفض في:</strong> {{ rejection_date }}</p><p style="margin-left:0;"><strong>سبب الرفض:</strong> {{ rejection_reason }}</p><p>تبقى الفعالية نشطة على منصتنا. إذا كانت لديك أي أسئلة حول هذا القرار أو كنت بحاجة إلى مساعدة إضافية، يرجى التواصل مع فريق الدعم لدينا.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('93', '2025-12-04 16:12:36', '2026-03-12 12:40:57', 0, NULL, 'scan_permission_granted', 'Scan Permission Granted', '<p>Dear {{ user_name }},</p><p>Your scan permission for {{ entity_type }} <strong>{{ entity_title }}</strong> has been granted.</p><p>You can now scan participants for this {{ entity_type }} using your account.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('75', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'event_deletion_request_admin', 'Event Deletion Request', '<p>Dear Admin,</p>\n                    <p>A deletion request has been submitted for the event: <strong>{{ event.title_en }}</strong>.</p>\n                    <div style="background-color: #f9f9f9; padding: 15px; border-radius: 8px; margin: 15px 0; text-align: left;">\n                        <p style="margin-top: 0;"><strong>Event Title:</strong> {{ event.title_en }}</p>\n                        <p><strong>Created By:</strong> {{ event.created_by.user.get_full_name }}</p>\n                        <p><strong>Creator Email:</strong> {{ event.created_by.user.email }}</p>\n                        <p><strong>Start Date:</strong> {{ event.start_date }}</p>\n                        <p><strong>End Date:</strong> {{ event.end_date }}</p>\n                        <p><strong>Due Date:</strong> {{ event.due_date }}</p>\n                        <p><strong>Request Date:</strong> {{ request_date }}</p>\n                        <p style="margin-bottom: 0;"><strong>Request Reason:</strong> {{ reason|default:"No reason provided" }}</p>\n                    </div>\n                    <p>Please click the link below to view details and take action:</p>\n                    <p><a href="{{ deep_link }}">View Details</a></p>\n                    <p>Best regards,<br>The Forsa Team</p>', 'en'),
('91', '2025-12-04 16:12:36', '2026-03-12 12:28:06', 0, NULL, 'role_update_notification', 'Update on Your Opportunity Role', '<p>Dear {{ user.get_full_name }},</p><p>The role you are registered for in the opportunity <strong>{{ opportunity.title_en }}</strong> has been updated.</p><p>Please log in to your account to view the updated details.</p><p>Thank you for your continued contribution and commitment!</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('90', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'admin_user_ban_notification_low_attendance', 'تم حظر مستخدم مؤقتاً بسبب قلة الحضور', '<p>مرحباً المشرف,</p>\n                    <p>تم حظر مستخدم مؤقتاً من المنصة بسبب عدم الحضور.</p>\n                    <div style="margin: 20px 0; padding: 15px; border: 1px solid #eee; border-radius: 5px;">\n                        <p><strong>تفاصيل المستخدم المحظور:</strong></p>\n                        <ul style="text-align: left; padding-left: 20px;">\n                            <li>الاسم: {{ banned_user_full_name }}</li>\n                            <li>البريد الإلكتروني: {{ banned_user.email }}</li>\n                            <li>الفرص المفوتة: {{ non_attended_count }}</li>\n                            <li>الحالة: محظور مؤقتاً</li>\n                            <li>المدة: سيتم رفع الحظر تلقائياً بعد 1 شهر</li>\n                        </ul>\n                    </div>\n                    <p>يرجى مراجعة حساب المستخدم في لوحة تحكم المشرف لاتخاذ أي إجراء إضافي إذا لزم الأمر.</p>\n                    <p>أطيب التحيات,<br>نظام المتطوعين</p>', 'ar'),
('83', '2025-12-04 16:12:36', '2026-03-12 12:38:45', 0, NULL, 'user_unban_email', 'Your Account Has Been Unbanned', '<p>Hello {{ user.first_name|default:"User" }},</p><p>Your account has been unbanned. You can now access the platform again.</p><p>We look forward to your continued participation.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('85', '2025-12-04 16:12:36', '2026-03-12 12:40:27', 0, NULL, 'user_ban_notification_low_attendance', 'Account Temporarily Banned Due to Low Attendance', '<p>Hello {{ user.first_name|default:"User" }},</p><p>Your account has been temporarily banned due to non-attendance at <strong>{{ non_attended_count }}</strong> volunteer opportunities.</p><p style="margin-left:0;"><strong>Ban Details:</strong></p><ul><li><p style="margin-left:0;">Email: {{ user.email }}</p></li><li><p style="margin-left:0;">Missed Opportunities: {{ non_attended_count }}</p></li><li><p style="margin-left:0;">Status: Temporarily Banned</p></li><li><p style="margin-left:0;">Duration: Your account will be automatically unbanned after 1 month</p></li></ul><p>We value your participation and look forward to your return after the ban period.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('87', '2025-12-04 16:12:36', '2026-03-12 12:40:38', 0, NULL, 'user_ban_notification_by_admin', 'Your Account Has Been Banned', '<p>Hello {{ user.first_name|default:"User" }},</p><p>Your account has been banned for the following reason:</p><p><strong>{{ reason }}</strong></p><p>If you have any questions, please contact support.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('92', '2025-12-04 16:12:36', '2026-03-12 12:50:11', 0, NULL, 'role_update_notification', 'تحديث على دورك في الفرصة', '<p>عزيزي {{ user.get_full_name }},</p><p>لقد تم تحديث الدور الذي قمت بالتسجيل له في الفرصة <strong>{{ opportunity.title_en }}</strong>.</p><p>يرجى تسجيل الدخول إلى حسابك لعرض التفاصيل المحدثة.</p><p>شكراً لك على مساهمتك والتزامك المستمر!</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('84', '2025-12-04 16:12:36', '2026-03-12 12:51:48', 0, NULL, 'user_unban_email', 'تم رفع الحظر عن حسابك', '<p>مرحباً {{ user.first_name|default:"المستخدم" }},</p><p>تم رفع الحظر عن حسابك. يمكنك الآن الوصول إلى المنصة مرة أخرى.</p><p>نتطلع إلى استمرار مشاركتك.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('86', '2025-12-04 16:12:36', '2026-03-12 12:51:51', 0, NULL, 'user_ban_notification_low_attendance', 'تم حظر الحساب مؤقتاً بسبب قلة الحضور', '<p>مرحباً {{ user.first_name|default:"المستخدم" }},</p><p>تم حظر حسابك مؤقتاً بسبب عدم الحضور إلى <strong>{{ non_attended_count }}</strong> فرص تطوعية.</p><p style="margin-left:0;"><strong>تفاصيل الحظر:</strong></p><ul><li><p style="margin-left:0;">البريد الإلكتروني: {{ user.email }}</p></li><li><p style="margin-left:0;">الفرص المفوتة: {{ non_attended_count }}</p></li><li><p style="margin-left:0;">الحالة: محظور مؤقتاً</p></li><li><p style="margin-left:0;">المدة: سيتم رفع الحظر عن حسابك تلقائياً بعد 1 شهر</p></li></ul><p>نحن نقدر مشاركتك ونتطلع إلى عودتك بعد فترة الحظر.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('88', '2025-12-04 16:12:36', '2026-03-12 12:51:54', 0, NULL, 'user_ban_notification_by_admin', 'تم حظر حسابك', '<p>مرحباً {{ user.first_name|default:"المستخدم" }},</p><p>تم حظر حسابك للسبب التالي:</p><p><strong>{{ reason }}</strong></p><p>إذا كانت لديك أي أسئلة، يرجى التواصل مع الدعم.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('98', '2025-12-04 16:12:36', '2026-01-19 06:21:18', 0, NULL, 'volunteer_three_day_reminder', 'تذكير: الفرصة التطوعية بعد 3 أيام', '<p>عزيزي {{ user_name }},</p>\n                    <p>هذه رسالة تذكير بأن الفرصة التطوعية <strong>{{ opportunity_title }}</strong> ستبدأ بعد 3 أيام ({{ start_date }})،</p>\n                    <p>نتطلع إلى مشاركتك!</p>\n                    <p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('115', '2025-12-04 16:12:36', '2026-03-12 12:26:48', 0, NULL, 'learnserve_unregister_notification', 'You have been removed from an opportunity', '<p>Dear {{ user.get_full_name }},</p><p>You have been unregistered from opportunity:</p><p><strong>{{ opportunity.title_en }}</strong></p><p>If you believe this was done by mistake or require further assistance, please contact the opportunity organizer.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('108', '2025-12-04 16:12:36', '2026-03-12 12:20:54', 0, NULL, 'learnserve_completion_notification', 'شكرًا: تم الانتهاء من الفرصة', '<p>عزيزي {{ user_name }},</p><p>شكرًا لمشاركتك في فرصة تعلم وشارك <strong>{{ opportunity_title }}</strong> التي انتهت في {{ end_date }}.</p><p>لقد أحدثت فرقًا بمشاركتك!</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('97', '2025-12-04 16:12:36', '2026-03-12 12:27:42', 0, NULL, 'volunteer_three_day_reminder', 'Reminder: Volunteer Opportunity in 3 Days', '<p>Dear {{ user_name }},</p><p>This is a reminder that the volunteer opportunity <strong>{{ opportunity_title }}</strong> starts in 3 days ({{ start_date }}).</p><p>We look forward to your participation!</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('104', '2025-12-04 16:12:36', '2026-03-12 12:24:23', 0, NULL, 'learnserve_three_day_reminder', 'تذكير: الفرصة بعد 3 أيام', '<p>عزيزي {{ user_name }},</p><p>فرصة &nbsp;<strong>{{ opportunity_title }}</strong> ستبدأ بعد 3 أيام ({{ start_date }}).</p><p>نتطلع إلى مشاركتك معنا!</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('103', '2025-12-04 16:12:36', '2026-03-12 12:24:38', 0, NULL, 'learnserve_three_day_reminder', 'Reminder: Opportunity in 3 days', '<p>Dear {{ user_name }},</p><p>Your opportunity <strong>{{ opportunity_title }}</strong> starts in 3 days ({{ start_date }}).</p><p>We\'re excited to have you onboard!</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('101', '2025-12-04 16:12:36', '2026-03-12 12:27:56', 0, NULL, 'volunteer_completion_notification', 'Thank You: Volunteer Opportunity Completed', '<p>Dear {{ user_name }},</p><p>Thank you for participating in the volunteer opportunity <strong>{{ opportunity_title }}</strong> which completed on {{ end_date }}.</p><p>We truly appreciate your efforts and contribution!</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('94', '2025-12-04 16:12:36', '2026-03-12 12:52:06', 0, NULL, 'scan_permission_granted', 'تم منح إذن المسح', '<p>عزيزي {{ user_name }},</p><p>لقد تم منح إذن المسح الخاص بك لـ {{ entity_type }} <strong>{{ entity_title }}</strong>.</p><p>يمكنك الآن مسح المشاركين في هذا {{ entity_type }} باستخدام حسابك.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('107', '2025-12-04 16:12:36', '2026-03-12 12:26:27', 0, NULL, 'learnserve_completion_notification', 'Thank You: Opportunity Completed', '<p>Dear {{ user_name }},</p><p>Thank you for completing the Learn &amp; Share opportunity <strong>{{ opportunity_title }}</strong> on {{ end_date }}.</p><p>Your involvement made a difference!</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('105', '2025-12-04 16:12:36', '2026-03-12 12:26:36', 0, NULL, 'learnserve_day_of_notification', 'Reminder: Today is the day of opportunity.', '<p>Dear {{ user_name }},</p><p>Your opportunity <strong>{{ opportunity_title }}</strong> starts today ({{ start_date }}).</p><p>We\'re glad to have you join us.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('95', '2025-12-04 16:12:36', '2026-03-12 12:41:05', 0, NULL, 'scan_permission_revoked', 'Scan Permission Revoked', '<p>Dear {{ user_name }},</p><p>Your scan permission for {{ entity_type }} <strong>{{ entity_title }}</strong> has been revoked.</p><p>You no longer have access to scan participants for this {{ entity_type }}.</p><p>Best Regards,<br>Forsa Team</p>', 'en'),
('96', '2025-12-04 16:12:36', '2026-03-12 12:52:04', 0, NULL, 'scan_permission_revoked', 'تم إلغاء إذن المسح', '<p>عزيزي {{ user_name }},</p><p>لقد تم إلغاء إذن المسح الخاص بك لـ {{ entity_type }} <strong>{{ entity_title }}</strong>.</p><p>لم يعد لديك حق الوصول لمسح المشاركين في هذا {{ entity_type }}.</p><p>أطيب التحيات,<br>فريق فرصة</p>', 'ar'),
('116', '2025-12-04 16:12:36', '2026-03-12 12:24:49', 0, NULL, 'learnserve_unregister_notification', 'تمت إزالتك من الفرصة', '<p>عزيزي {{ user.get_full_name }},</p><p>لقد تم إلغاء تسجيلك من فرصة :</p><p><strong>{{ opportunity.title_ar }}</strong></p><p>إذا كنت تعتقد أن هذا حدث عن طريق الخطأ أو تحتاج إلى مساعدة إضافية، يرجى التواصل مع منظم الفرصة.</p><p><br>&nbsp;</p><p>مع أطيب التحيات,<br>فريق فرصة</p>', 'ar');
INSERT INTO `faqs` (`id`, `created_at`, `updated_at`, `is_deleted`, `deleted_at`, `question_en`, `question_ar`, `answer_en`, `answer_ar`) VALUES
('5', '2025-12-05 05:38:32', '2025-12-05 05:38:32', 0, NULL, 'What are the available volunteering fields?', 'ما هي مجالات التطوع المتاحة؟', '<ol><li>Charitable (e.g., aid distribution)</li><li>Emergency response (e.g., disaster relief)</li><li>Organizational (e.g., event coordination)</li><li>Professional (e.g., specialized services)</li><li>Consultations, courses, and experiences in various fields</li></ol>', '• المجالات تشمل:<ul><li>خيرية (مثل توزيع المساعدات).</li><li>إغاثية (الاستجابة للكوارث).</li><li>تنظيمية (تنظيم فعاليات ومبادرات).</li><li>مهنية (تقديم خدمات تخصصية).</li><li>استشارات، دورات، وخبرات في مختلف المجالات.</li></ul>'),
('6', '2025-12-05 05:38:32', '2025-12-05 05:38:32', 0, NULL, 'What are the registration requirements?', 'ما هي معايير التسجيل في المنصة؟', 'Registration is open to everyone Kuwaiti citizens and residents aged 7 years and above.', '• التسجيل متاح للجميع كويتي أو مقيم ولكل من بلغ 7 سنوات فأكثر.'),
('7', '2025-12-05 05:38:32', '2025-12-05 05:38:32', 0, NULL, 'Can children participate?', 'هل يمكن للأطفال المشاركة؟', 'Yes, children can join with parental attendance, and only in age-appropriate opportunities (clearly stated with each opportunity).', '• نعم، يمكن للأطفال المشاركة بشرط حضور ولي الأمر، وذلك في الفرص المخصصة لفئتهم العمرية، حيث يتم توضيح العمر المناسب لكل فرصة عند عرضها.'),
('3', '2025-12-05 05:38:32', '2026-03-21 12:05:54', 0, NULL, 'What Volunteer Teams can do via "Forsa"?', 'ما الذي يمكن للفرق التطوعية فعله عبر "فرصة"؟', '<ol>\r\n  <li>Launch Initiatives: Launch initiatives and recruit qualified volunteers.</li>\r\n  <li>Organize Courses: Organize courses and training programs that serve the community.</li>\r\n  <li>Showcase Events: List free or paid activities in the Events section within the platform.</li>\r\n  <li>Compete: Earn your spot among the top 10 volunteer teams on the "Achievements" page.</li>\r\n  <li>Track Performance: View precise metrics on your profile, including opportunities and volunteer hours.</li>\r\n</ol>', '<ol>\r\n  <li>إطلاق مبادرات واستقطاب متطوعين: بناء المبادرات وجذب الكفاءات المؤهلة للمشاركة فيها.</li>\r\n  <li>تنظيم ورش وفعاليات تعليمية: إقامة برامج تدريبية وورش عمل مجتمعية متكاملة.</li>\r\n  <li>عرض الفعاليات المتنوعة: النشر في قسم الفعاليات داخل المنصة، سواء كانت مجانية أو مدفوعة.</li>\r\n  <li>التنافس ضمن أفضل 10 فرق تطوعية: التميز والظهور في قائمة الفرق الأكثر تأثيراً في "الإنجازات".</li>\r\n  <li>تتبع الأداء: توثيق وعرض إحصائيات دقيقة في ملفكم التعريفي (الفرص، الساعات).</li>\r\n</ol>'),
('4', '2025-12-05 05:38:32', '2026-03-21 12:09:27', 0, NULL, 'What entities can do via "Forsa"?', 'ما الذي يمكن للجهات والشركات فعله عبر "فرصة"؟', '<ol>\r\n  <li>Launch Initiatives: Launch initiatives and recruit qualified volunteers.</li>\r\n  <li>Organize Courses: Organize courses and training programs that serve the community.</li>\r\n  <li>Showcase Events: List free or paid activities in the Events section.</li>\r\n  <li>Support Ideas: Turn "Forsa Community" volunteer ideas into reality.</li>\r\n  <li>Access Profiles: Browse volunteer profiles to find the perfect match.</li>\r\n  <li>Compete: Earn your spot among the top 10 on the "Achievements" page.</li>\r\n  <li>Track Performance: View precise metrics on your profile, including opportunities, hours, and sponsorships.</li>\r\n</ol>', '<ol>\r\n  <li>إطلاق المبادرات واستقطاب المتطوعين: إطلاق المبادرات واستقطاب المتطوعين المؤهلين حسب المهارات.</li>\r\n  <li>تنظيم دورات وورش العمل: تنظيم البرامج التدريبية والدورات التي تخدم المجتمع.</li>\r\n  <li>عرض الفعاليات: أدرج الأنشطة المجانية أو المدفوعة في قسم الفعاليات داخل المنصة.</li>\r\n  <li>دعم الأفكار: حوّل أفكار التطوع في "مجتمع فورسا" إلى واقع ملموس بدعمكم ورعايتكم.</li>\r\n  <li>الوصول إلى الملفات الشخصية: تصفّح ملفات المتطوعين للعثور على الشخص المناسب لمبادراتكم.</li>\r\n  <li>التنافس: احصل على مكانك بين النخبة في صفحة "الإنجازات".</li>\r\n  <li>تتبع الأداء: توثيق وعرض إحصائيات دقيقة في ملفكم التعريفي (الفرص، الساعات، الرعايات).</li>\r\n</ol>'),
('1', '2025-12-05 05:38:32', '2026-03-22 15:51:43', 0, NULL, 'What is "Forsa"?', 'ما هي منصة "فرصة"؟', '"Forsa" is an innovative platform aimed at promoting a culture of volunteering and empowering individuals to find volunteer opportunities that match their interests and aspirations. It acts as a bridge connecting volunteers with entities and volunteer teams in need of support across various fields.', '"فرصة" هي منصة مبتكرة تهدف إلى تعزيز ثقافة التطوع وتمكين الأفراد من إيجاد فرص تطوعية تتناسب مع اهتماماتهم وتطلعاتهم. تعمل كجسر يربط المتطوعين بالجهات والفرق التطوعية التي تحتاج للدعم في مختلف المجالات.'),
('9', '2025-12-05 05:38:32', '2025-12-05 05:38:32', 0, NULL, 'Can people with disabilities participate?', 'هل يمكن للأشخاص ذوي الهمم المشاركة؟', 'Yes, provided the activities are compatible with their needs and an inclusive environment is available to ensure full participation.', '• نعم، بشرط توافق الأنشطة مع احتياجاتهم وتتوفر بيئة شاملة لضمان مشاركتهم الفعالة.'),
('10', '2025-12-05 05:38:32', '2025-12-05 05:38:32', 0, NULL, 'Can non-Arabic speakers join?', 'هل يمكن للأشخاص الناطقين بلغات أخرى المشاركة؟', 'Yes, participation is open to everyone, though some opportunities may require Arabic proficiency depending on the activity.', 'نعم، المشاركة متاحة للجميع، لكن بعض الفرص قد تتطلب إتقان اللغة العربية حسب طبيعة النشاط.'),
('11', '2025-12-05 05:38:32', '2025-12-05 05:38:32', 0, NULL, 'Can I cancel my registration after signing up?', 'هل يمكن الاعتذار عن المشاركة بعد التسجيل؟', 'Yes, you can cancel by clicking "Unregister." It\'s preferred to notify the organizer in advance to ensure continuity.', 'نعم، من خلال الضغط على إلغاء التسجيل ويفضل إبلاغ المنظم مسبقًا بوقت كافٍ لضمان الاستمرارية.'),
('13', '2025-12-05 05:38:33', '2025-12-05 05:38:33', 0, NULL, 'How can I propose a volunteer idea?', 'كيف يمكنني طرح فكرة تطوعية؟', 'Via the "Forsa Community" page, click "Share" then choose "Idea or Idea needs fund."', 'من خلال صفحة "مجتمع فرصة"، عبر الضغط على "شارك" واختيار "فكرة أو فكرة تحتاج دعم".'),
('14', '2025-12-05 05:38:33', '2025-12-05 05:38:33', 0, NULL, 'Can a volunteer be removed or replaced?', 'هل يمكن الاستغناء عن متطوع أو إضافة متطوع آخر؟', 'Yes, based on actual needs or performance evaluation.', 'نعم، حسب الاحتياج الفعلي أو تقييم الأداء.'),
('2', '2025-12-05 05:38:32', '2026-03-21 12:05:08', 0, NULL, 'What Volunteer can do via "Forsa"?', 'ما الذي يمكن للمتطوع فعلة عبر "فرصة"؟', '<ol>\r\n  <li>Join Opportunities: Find volunteer roles based on your interests, with your hours automatically tracked in your profile.</li>\r\n  <li>Participate in Courses: Join free training programs and earn certificates of attendance from Forsa or the organizer.</li>\r\n  <li>Access Free Services: Benefit from services (such as consultations, education, sports, etc.) provided by volunteering entities.</li>\r\n  <li>Rate and Review: Share your feedback on courses, consultations, and events.</li>\r\n  <li>Share Ideas: Post on the "Forsa Community" to gain support from sponsors.</li>\r\n  <li>Track Achievements: Showcase your volunteer hours and certificates on your profile.</li>\r\n  <li>Compete: Earn your spot among the top 10 volunteers on the "Achievements" board.</li>\r\n</ol>', '<ol>\r\n  <li>الانضمام إلى الفرص التطوعية: حسب اهتماماتك، مع احتساب ساعات التطوع في ملفك الشخصي.</li>\r\n  <li>المشاركة في دورات تدريبية مجانية: والحصول على شهادات حضور سواء من المنصة أو الجهة المنظمة.</li>\r\n  <li>الاستفادة من خدمات مجانية: (استشارات، تعليم، رياضة...) مقدمة من جهات متطوعة.</li>\r\n  <li>تقييم الدورات والاستشارات والفعاليات: والمساهمة في تطوير تجربة المستخدم.</li>\r\n  <li>مشاركة أفكارك في صفحة "مجتمع فرصة": للحصول على دعم الجهات الراعية والمؤسسات الشريكة.</li>\r\n  <li>توثيق الإنجازات: توثيق الساعات والشهادات في ملفك الشخصي لتكون مرجعاً دائماً لك.</li>\r\n  <li>التنافس ضمن أفضل 10 متطوعين: في صفحة "الإنجازات" للحصول على التقدير المستحق.</li>\r\n</ol>'),
('12', '2025-12-05 05:38:33', '2026-03-21 12:10:35', 0, NULL, 'What is expected from volunteers, entities , and teams?', 'ما المتوقع من المتطوعين، الجهات، والفرق التطوعية؟', '<ul>\r\n  <li><strong>Volunteers:</strong> Commitment, engagement, and respect.</li>\r\n  <li><strong>Teams:</strong> Publish volunteer opportunities and document volunteer achievements.</li>\r\n  <li><strong>Entities:</strong> Support volunteering by publishing opportunities or providing financial or in-kind support.</li>\r\n</ul>', '<ul>\r\n  <li><strong>المتطوعون:</strong> الالتزام، الفعالية، والاحترام.</li>\r\n  <li><strong>الفرق:</strong> نشر الفرص التطوعية وتوثيق إنجازات المتطوعين.</li>\r\n  <li><strong>الجهات:</strong> دعم التطوع من خلال نشر الفرص أو تقديم الدعم المادي والعيني.</li>\r\n</ul>'),
('15', '2025-12-05 05:38:33', '2026-03-21 12:12:01', 0, NULL, 'How are achievements calculated?', 'كيف تُحسب إنجازات التطوع؟', '<ol>\r\n  <li>For Volunteers: After participating, the organizer will record your attendance, and your hours will be automatically added to the record.</li>\r\n  <li>For Entities and Teams: Once the volunteer opportunity is completed and attendance is recorded, the initiative and hours are automatically added to the record.</li>\r\n</ol>', '<ol>\r\n  <li>للمتطوع: بعد المشاركة، يقوم منظم الفرصة بتسجيل حضورك، وتُضاف الساعات تلقائيًا إلى ملفك الشخصي.</li>\r\n  <li>للجهات والفرق: بعد إنجاز الفرصة التطوعية وتسجيل الحضور، تُدرج المبادرة وتُحسب الساعات تلقائياً في السجل.</li>\r\n</ol>'),
('16', '2025-12-05 05:38:33', '2026-03-21 12:12:45', 0, NULL, 'Certificates (FORSA certificates)?', 'الشهادات (شهادة فرصة)؟', 'After completing a course and confirming attendance, your certificate will appear digitally in your profile.', 'بعد إتمام الدورة وتأكيد الحضور من المنظم، تُعرض الشهادة إلكترونيًا في ملفك الشخصي.'),
('17', '2025-12-05 05:38:33', '2026-03-21 12:13:06', 0, NULL, 'How can entities support us?', 'كيف يمكن للجهات دعمنا؟', 'Organizations can submit a sponsorship offer through the "Sponsors" page on the platform (Join Our Partners), where you can choose the type of support that suits you. The dedicated team will contact you after reviewing the request.', 'من خلال تقديم عرض الرعاية عبر صفحة "الرعاة" على المنصة (انضم لشركائنا)، حيث يمكنكم اختيار نوع الدعم المناسب وسيتم التواصل معكم من قبل الفريق المختص بعد مراجعة الطلب.');
INSERT INTO `notifications` (`id`, `created_at`, `updated_at`, `is_deleted`, `deleted_at`, `message_ar`, `message_en`, `title_ar`, `title_en`) VALUES
('1', '2025-12-04 14:19:17', '2025-12-04 14:19:17', 0, NULL, 'تمت إضافة راعي جديد \'Forsa\' إلى المنصة. نوع الراعي هو Financial Support. يرجى مراجعته في لوحة الإدارة.', 'A new sponsor \'Forsa\' has been added to the platform. The sponsor type is Financial Support. Please review it in the admin panel.', 'تمت إضافة راعي جديد: Forsa في 04/12/2025', 'New Sponsor Added: Forsa on December 04, 2025'),
('2', '2025-12-04 14:31:09', '2025-12-04 14:31:09', 0, NULL, 'تمت إضافة راعي جديد \'Oren Rios\' إلى المنصة. نوع الراعي هو Financial Support. يرجى مراجعته في لوحة الإدارة.', 'A new sponsor \'Oren Rios\' has been added to the platform. The sponsor type is Financial Support. Please review it in the admin panel.', 'تمت إضافة راعي جديد: Oren Rios في 04/12/2025', 'New Sponsor Added: Oren Rios on December 04, 2025'),
('3', '2025-12-04 14:45:25', '2025-12-04 14:45:25', 0, NULL, 'تمت الموافقة على فرصة التطوع الخاصة بك \'Volunteership program\'.', 'Your volunteer opportunity \'Volunteership program\' has been approved.', 'تمت الموافقة على فرصة التطوع', 'Volunteer Opportunity Approved'),
('4', '2025-12-04 14:55:28', '2025-12-04 14:55:28', 0, NULL, 'تمت الموافقة على فرصة التعلم والخدمة الخاصة بك \'Learn\'.', 'Your learn & Share opportunity \'Learn\' has been approved.', 'تمت الموافقة على فرصة التعلم والخدمة', 'Learn & Share Opportunity Approved'),
('5', '2025-12-05 09:28:30', '2025-12-05 09:28:30', 0, NULL, 'تم تأكيد تسجيلك في فرصة التعلم والخدمة هذه. تم تحديد موعد الحدث في 08/12/2025. نتطلع إلى مشاركتك!', 'Your registration for this Learn & Share opportunity is confirmed. The event is scheduled for Monday, December 08, 2025. We look forward to your participation!', 'لقد سجلت بنجاح في \'Opportunity\' في 05/12/2025', 'You\'ve successfully registered for \'Opportunity\' on December 05, 2025'),
('6', '2025-12-05 09:28:30', '2025-12-05 09:28:30', 0, NULL, 'قام Rishita Mehta بالتسجيل في فرصة التطوع الخاصة بك في 05/12/2025 الساعة 09:28 AM.', 'Rishita Mehta has registered for your volunteer opportunity on December 05, 2025 at 09:28 AM.', 'تسجيل جديد في فرصة \'Opportunity\' الخاصة بك', 'New registration for your \'Opportunity\' opportunity'),
('7', '2025-12-08 09:35:15', '2025-12-08 09:35:15', 0, NULL, 'فرصتك التطوعية \'Opportunity\' تبدأ اليوم في 12:00:00! نتطلع إلى مشاركتك.', 'Your volunteer opportunity \'Opportunity\' starts today at 12:00:00! We look forward to your participation.', 'اليوم: فرصة تطوعية - Opportunity', 'Today: Volunteer Opportunity - Opportunity'),
('8', '2025-12-09 07:30:20', '2025-12-09 07:30:20', 0, NULL, 'شكرًا لمشاركتك في \'Opportunity\' التي اكتملت في 2025-12-08. نحن نقدر مساهمتك!', 'Thank you for participating in \'Opportunity\' which completed on 2025-12-08. We appreciate your contribution!', 'شكرًا: اكتملت الفرصة التطوعية - Opportunity', 'Thank You: Volunteer Opportunity Completed - Opportunity'),
('9', '2025-12-09 07:35:05', '2025-12-09 07:35:05', 0, NULL, 'شكرًا لمشاركتك في \'Opportunity\' التي اكتملت في 2025-12-08. نحن نقدر مساهمتك!', 'Thank you for participating in \'Opportunity\' which completed on 2025-12-08. We appreciate your contribution!', 'شكرًا: اكتملت الفرصة التطوعية - Opportunity', 'Thank You: Volunteer Opportunity Completed - Opportunity'),
('10', '2025-12-10 19:13:16', '2025-12-10 19:13:16', 0, NULL, 'قام المنظم بتسجيلك في \'ي\'. تم جدولة الحدث في 11/12/2025. يرجى التحقق من بريدك الإلكتروني لمزيد من التفاصيل.', 'The organizer has registered you for \'Y\'. The event is scheduled for Thursday, December 11, 2025. Please check your email for more details.', 'تم تسجيلك في \'ي\' من قبل المنظم في 10/12/2025', 'You\'ve been registered for \'Y\' by the organizer on December 10, 2025'),
('11', '2025-12-10 19:15:14', '2025-12-10 19:15:14', 0, NULL, 'قام المنظم بإلغاء تسجيلك من فرصة التطوع \'ي\' في 10/12/2025 الساعة 07:15 PM.', 'The organizer has unregistered you from the volunteer opportunity \'Y\' on December 10, 2025 at 07:15 PM.', 'تم إلغاء تسجيلك من \'ي\' من قبل المنظم', 'You\'ve been unregistered from \'Y\' by the organizer'),
